def transform(grid):
    """Overlay the two fields separated by a solid divider; mark intersections."""
    divider = next(i for i in range(len(grid[0])) if all(row[i] != 0 for row in grid))
    left_width = divider
    right_start = divider + 1
    return [
        [2 if grid[r][c] != 0 and grid[r][right_start + c] != 0 else 0
         for c in range(left_width)]
        for r in range(len(grid))
    ]
